//! Weight functions for pallet-ict-consensus. `()` holds the estimates used until the runtime ships
//! benchmarked weights (runtime/src/weights/, generated by scripts/run-benchmarks.sh).
#![allow(unused_parens, unused_imports)]

use polkadot_sdk::frame_support::weights::{constants::RocksDbWeight, Weight};

pub trait WeightInfo {
    fn stake() -> Weight;
    fn unstake() -> Weight;
    fn withdraw_unstaked() -> Weight;
    fn claim_launch_rewards() -> Weight;
    fn settle(v: u32, n: u32) -> Weight;
}

impl WeightInfo for () {
    fn stake() -> Weight {
        RocksDbWeight::get().reads_writes(3, 3)
    }
    fn unstake() -> Weight {
        RocksDbWeight::get().reads_writes(3, 3)
    }
    fn withdraw_unstaked() -> Weight {
        RocksDbWeight::get().reads_writes(1, 1)
    }
    fn claim_launch_rewards() -> Weight {
        RocksDbWeight::get().reads_writes(4, 2)
    }
    fn settle(v: u32, n: u32) -> Weight {
        RocksDbWeight::get().reads_writes(10 + v as u64 + 3 * n as u64, 4 + 2 * n as u64)
    }
}
